import React from 'react';
import { Paper } from '@material-ui/core'
import { useStyles } from './StyleMaterialUI'


const DialogMainPhoto = ({activeData}) => {

    const classes = useStyles();

    return (
        <>
            {/* IF THERE ARE PHOTOS */}
            {(activeData.MediaItems && activeData.MediaItems[0].ItemURL) ? 
            activeData.MediaItems.map((item) => (
                <Paper
                    key={item.ID}
                    elevation={5} 
                    className={classes.dialogPhotos}>
                    <img src={item.ItemURL} alt="" className={classes.chargerImages}></img>
                    <div
                        style={{padding: '0.4rem'}}
                        className={classes.gray}><span className={classes.bold}>Taken By </span>{item.User.Username}</div>
                </Paper>
            ))
            : ""}
        </>
    )
}

export default DialogMainPhoto
