import React from "react";
import { Grid, Button } from "@material-ui/core";
import PhotoCameraIcon from "@material-ui/icons/PhotoCamera";
import PublicIcon from "@material-ui/icons/Public";
import ExitToAppIcon from "@material-ui/icons/ExitToApp";

import { useStyles } from "./StyleMaterialUI";

const DialogFooter = ({
  toggleDialog,
  activeData,
  disblePhotoButton,
  togglePhoto,
  isOpenPhoto,
}) => {
  const classes = useStyles();

  // Google View By Lat and Lng
  const googleStreetView = (lat, lng) => {
    const url = `https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${lat},${lng}`;
    return url;
  };

  return (
    <>
      <Grid container justify="center" spacing={1}>
        <Grid item xs={6}>
          {!isOpenPhoto ? (
            <Button
              disabled={disblePhotoButton(activeData.MediaItems)}
              variant="contained"
              color="secondary"
              onClick={togglePhoto}
              startIcon={<PhotoCameraIcon fontSize="large" />}
              size="large"
              className={classes.dialogButton}
            >
              Photos
            </Button>
          ) : (
            <Button
              variant="contained"
              onClick={togglePhoto}
              color="secondary"
              startIcon={<ExitToAppIcon fontSize="large" />}
              size="large"
              className={classes.dialogButton}
            >
              Main
            </Button>
          )}
        </Grid>
        <Grid item xs={6}>
          <Button
            href={googleStreetView(
              activeData.AddressInfo.Latitude,
              activeData.AddressInfo.Longitude
            )}
            variant="contained"
            color="secondary"
            target="_blank"
            startIcon={<PublicIcon fontSize="large" />}
            size="large"
            className={classes.dialogButton}
          >
            Google View
          </Button>
        </Grid>
        <Grid item xs={12}>
          <Button
            variant="contained"
            color="primary"
            onClick={toggleDialog}
            endIcon={<ExitToAppIcon fontSize="large" />}
            size="large"
            className={classes.dialogButton}
          >
            Go Back
          </Button>
        </Grid>
      </Grid>
    </>
  );
};

export default DialogFooter;
