import { makeStyles } from "@material-ui/core/styles";

export const useStyles = makeStyles({
  // ****************** NAVBAR *******************
  navbar: {
    padding: 0,
    margin: 0,
    position: "absolute",
  },
  navHeading: {
    color: "white",
    textTransform: "uppercase",
    fontSize: "2rem",
    height: "100%",
    display: "inline-block",
    padding: "0.5rem 2rem 0.5rem 2rem",
    fontWeight: "bold",
    letterSpacing: "4px",
    cursor: "pointer",
    "@media (max-width: 600px)": {
      fontSize: "1.5rem",
      paddingLeft: "0.6rem",
      paddingRight: "0.6rem",
    },
    "@media (max-width: 320px)": {
      fontSize: "1.2rem",
      paddingLeft: "0.6rem",
      paddingRight: "0.6rem",
    },
  },
  navIcon: {
    position: "relative",
    top: "3px",
  },

  // ********* DIALOG *****************-
  dialogHead: {
    textTransform: "uppercase",
    fontWeight: "bold",
    textAlign: "center",
    color: "#f7f7f7",
    fontFamily: "Roboto, Helvetica, Arial, sans-serif",
  },
  dialogContact: {
    display: "flex",
    flexDirection: "column",
    width: "auto",
    height: "100%",
    padding: "0.3rem",
    justifyContent: "center",
    alignItems: "center",
    fontSize: "1.2rem",
    fontFamily: "Roboto, Helvetica, Arial, sans-serif",
  },
  dialogBasicInfo: {
    padding: "0.4rem",
    width: "auto",
    textAlign: "center",
    fontFamily: "Roboto, Helvetica, Arial, sans-serif",
  },
  dialogConnects: {
    display: "flex",
    flexDirection: "column",
    width: "auto",
    height: "100%",
    padding: "0.3rem",
    justifyContent: "center",
    alignItems: "center",
    fontFamily: "Roboto, Helvetica, Arial, sans-serif",
  },
  dialogButton: {
    width: "100%",
    minHeight: "auto",
    height: "100%",
    fontWeight: "bold",
    letterSpacing: "0.1rem",
    textAlign: "center",
    lineHeight: "1.3",
  },
  dialogPhotos: {
    display: "flex",
    flexDirection: "column",
    width: "auto",
    height: "100%",
    padding: "0.5rem",
    margin: "0.5rem",
    justifyContent: "center",
    alignItems: "center",
  },
  displayNone: {
    display: "none",
  },
  displayUnset: {
    display: "unset",
  },
  chargerImages: {
    width: "100%",
  },

  // ********* MAP *****************-
  mapContainer: {
    width: "100%",
    position: "absolute",
    height: "100vh",
  },

  // ********* SIDEBAR *****************-

  sideBarContainer: {
    position: "relative",
    width: "30vw",
    padding: "3rem 1rem 1rem 1rem",
    "@media (max-width: 992px)": {
      width: "50vw",
    },
    "@media (max-width: 600px)": {
      width: "100vw",
      padding: "0.5rem 0 0 0",
      paddingTop: "0.5rem",
    },
  },
  sideBarCloseButton: {
    position: "fixed",
    width: "60%",
    minHeight: "auto",
    fontWeight: "bold",
    letterSpacing: "0.1rem",
    textAlign: "center",
    lineHeight: "1.3",
    marginBottom: "1.5rem",
  },
  sidebarHeader: {
    margin: "0.5rem",
    textAlign: "center",
    textTransform: "uppercase",
    fontSize: "1.8rem",
    fontWeight: "bold",
    "@media (max-width: 600px)": {
      fontSize: "1.3rem",
    },
  },
  sidebarAbout: {
    textAlign: "center",
    padding: "1rem",
    fontSize: "0,8rem",
  },
  attrLink: {
    textDecoration: "none",
    fontWeight: "bold",
  },
  imgCharger: {
    width: "100%",
    borderRadius: "6px",
    boxShadow: "3px 3px 10px",
    marginTop: "2rem",
    "@media (max-width: 600px)": {
      width: "80%",
      marginBottom: "2rem",
    },
  },

  sidebarSubHeader: {
    textAlign: "center",
    padding: "0 0.5rem 0 0.5rem",
    textTransform: "uppercase",
    fontWeight: 400,
    fontSize: "1.2rem",
    letterSpacing: "1px",
    marginTop: "1rem",
    marginBottom: "1rem",
    "@media (max-width: 600px)": {
      fontSize: "1rem",
    },
  },
  sidFilterInput: {
    width: "70%",
    marginBottom: "1rem",
  },
  // ****************** OTHER *****************-
  boldGray: {
    color: "rgba(0, 0, 0, 0.87)",
    fontWeight: "bold",
  },
  gray: {
    color: "rgba(0, 0, 0, 0.54)",
  },
  error: {
    position: "absolute",
    top: 0,
    left: 0,
    zIndex: 3000,
    width: "100vw",
    height: "100Vh",
    background: "#cc0000",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  errorText: {
    letterSpacing: "3px",
    color: "#1D0000",
    fontSize: "1.6rem",
    fontWeight: 500,
    textTransform: "uppercase",
    textAlign: "center",
    padding: "1rem",
    lineHeight: "1.6",
  },
  loading: {
    position: "absolute",
    top: "50vh",
    left: "50vw",
    zIndex: 2001,
    marginLeft: "-25px",
    marginTop: "-25px",
  },
  spacing: {
    letterSpacing: "0.35rem",
    fontWeight: "bold",
  },
  bold: {
    fontWeight: "bold",
  },
  alignRight: {
    display: "flex",
    justifyContent: "flex-end",
  },
  alignCenter: {
    display: "flex",
    justifyContent: "center",
  },
});

