import React from 'react';
import DialogMainInfo from './DialogMainInfo';
import DialogMainPhoto from './DialogMainPhoto';
import { Typography, Dialog, DialogTitle, DialogContent, DialogActions } from "@material-ui/core";
import DialogFooter from './DialogFooter';
import { useStyles } from './StyleMaterialUI'


const MapDialog = ({ activeData, toggleDialog, isOpenDialog, togglePhoto, isOpenPhoto }) => {

  const classes = useStyles();

  // Disable Button If There are no photo
  const disblePhotoButton = (activeItem) => {
    if (activeItem && activeItem[0].ItemURL) {
      return false;
    } else {
      return true;
    }
  }

  return (
      <>
        {/* SHOW DIALOG ONLY IF THERE ARE SOME DATA */}
        {activeData ?
          <Dialog onBackdropClick={toggleDialog}
            fullWidth={true}
            scroll="paper"
            open={isOpenDialog} // Boolean true/false
            aria-labelledby="scroll-dialog-title"
            aria-describedby="scroll-dialog-description"
          >
            {/*********** DIALOG HEADER ****************/}
            <DialogTitle
              disableTypography
              style={{backgroundColor: '#1b5e20'}}
              className={classes.dialogHead}>
              <Typography variant="h5" className={classes.spacing}>
                {activeData.AddressInfo.Title}
              </Typography>
            </DialogTitle>

            {/*********** DIALOG BODY ****************/}
            <DialogContent dividers={true} className={isOpenPhoto ? classes.displayNone : classes.displayUnset}>
              <DialogMainInfo activeData={activeData} />
            </DialogContent>
            <DialogContent dividers={true} className={isOpenPhoto ? classes.displayUnset : classes.displayNone} >
              <DialogMainPhoto activeData={activeData} />
            </DialogContent>
            
            
            {/*********** DIALOG FOOTER/ACTIONS ****************/}
            <DialogActions>
              <DialogFooter 
              disblePhotoButton={disblePhotoButton} 
              toggleDialog={toggleDialog} 
              togglePhoto={togglePhoto} 
              activeData={activeData} 
              isOpenPhoto={isOpenPhoto}
              />
            </DialogActions>
          </Dialog>
        : ""} 
      </>
  )
}

export default MapDialog
